"use strict";(self.webpackChunknotes_by_sara=self.webpackChunknotes_by_sara||[]).push([["69272"],{20420(e){e.exports=JSON.parse('{"id":"FIN-260","slug":"bond-duration","term":"Bond Duration","also_known_as":[],"difficulty":"Intermediate","definition":"Bond duration measures how sensitive a bond\'s price is to changes in interest rates. It is expressed in years and can be used to estimate the percentage change in price for a one-percentage-point change in yield.","explanation":["Duration combines a bond\'s maturity and its coupon payments into a single number. Strictly, Macaulay duration is the weighted average time until the bond\'s payments are received. Modified duration, derived from it, estimates the price change for a change in yield.","As a rule of thumb, if a bond has a modified duration of 7, its price will fall by about 7% if yields rise by one percentage point, and rise by about 7% if yields fall by one percentage point.","For example, a ten-year bond with a 5% coupon priced at face value has a modified duration of about 7.7. A two-year bond would have a duration of under 2, so its price would change much less.","Longer maturities and lower coupons mean higher duration and greater interest rate risk. Investors use duration to manage this risk. Someone expecting rates to rise might shorten the duration of their bond portfolio. Duration is an approximation that works best for small changes in yield; for larger changes, convexity is used to refine the estimate."],"note":"","total":1500,"prev":{"slug":"bond","term":"Bond"},"next":{"slug":"bond-price","term":"Bond Price"}}')}}]);